clear
addpath('utils/')

%% Initialize MSEA model
configFile = "config.json";
params = initialize_msea_model(configFile);

% Extract x0 corresponding to config
x0 = params.initial.q_0(1);

%% Reference information file
referenceFile = 'reference_info.csv';

% Optional: delete old file before generating new reference map
if isfile(referenceFile)
    delete(referenceFile);
end

%% Define workspace range

% Position range relative to initial q_0
x_list = -0.07 : 0.01   :  0.02;   % m
y_list = -0.04 : 0.01 :  0.04;   % m
z_list = -0.04 : 0.01 :  0.04;   % m

% Orientation range
roll_list  = deg2rad(-3 : 0.5 : 3);   % rad
pitch_list = deg2rad(-3 : 0.5 : 3);   % rad
yaw_list   = deg2rad(-5 : 0.5 : 5);   % rad


total_points = numel(x_list) * numel(y_list) * numel(z_list) * ...
               numel(roll_list) * numel(pitch_list) * numel(yaw_list);
fprintf('Total candidate reference points: %d\n', total_points); %[output:42d745b5]


% Traverse working range
valid_count = 0;
skip_count = 0;

for ix = 1:numel(x_list) %[output:group:8ff5ac75]
    for iy = 1:numel(y_list)
        for iz = 1:numel(z_list)
            for ir = 1:numel(roll_list)
                for ip = 1:numel(pitch_list)
                    for iyaw = 1:numel(yaw_list)

                        q_rel = [
                            x_list(ix);
                            y_list(iy);
                            z_list(iz);
                            roll_list(ir);
                            pitch_list(ip);
                            yaw_list(iyaw)
                        ];

                        q_abs = q_rel;
                        q_abs(1) = q_abs(1) + x0;

                        [params_point, errorFlag] = solve_msea_state(q_abs, params);

                        if errorFlag
                            skip_count = skip_count + 1;
                            continue;
                        end

                        point_index = valid_count;

                        prepare_info(referenceFile, params_point, point_index);

                        valid_count = valid_count + 1;
                        fprintf('Saved point_index = %d, valid_count = %d\n', ... %[output:50225ebe]
                                point_index, valid_count); %[output:50225ebe]
                    end
                end
            end
        end
    end
end %[output:group:8ff5ac75]

fprintf('Finished.\n');
fprintf('Valid reference points: %d\n', valid_count);
fprintf('Skipped reference points: %d\n', skip_count);

